class Time {
    _observer;
    _step;
    _hours;
    _days;
    constructor(observer) {
        this._observer = observer;
        this._step = 0;
        this._hours = 0;
        this._days = 0;
    }
    getDays() {
        return this._days;
    }
    addHours(steps = 1) {
        this._step += steps;
        this._days = Math.floor(this._step / 24);
        this.updated();
    }
    subHours(steps = 1) {
        this._step -= steps;
        this._days = Math.floor(this._step / 24);
        this.updated();
    }
    getHours() {
        return this._step;
    }
    updated() {
        this._observer.updated();
    }
}
export default Time;
