class Player {
    _observer;
    _money;
    _level;
    _energy;
    _carts;
    constructor(observer) {
        this._observer = observer;
        this._carts = [];
        this._level = 0;
        this._money = 0;
        this._energy = 24;
    }
    addCart(cart) {
        this._carts.push(cart);
    }
    getCarts() {
        return this._carts;
    }
    getCartById(id) {
        return this._carts[id];
    }
    addMoney(money) {
        this._money += money;
        this.updated();
    }
    setMoney(money) {
        this._money = money;
    }
    money() {
        return this._money;
    }
    getEnergy() {
        return this._energy;
    }
    subEnergy(energy) {
        if (this._energy < energy) {
            throw new Error('Не хватает энергии');
        }
        this._energy -= energy;
        this.updated();
    }
    addEnergy(energy) {
        this._energy += energy;
        this.updated();
    }
    level() {
        return this._level;
    }
    updated() {
        this._observer.updated();
    }
}
export default Player;
